"use strict";
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[[6,8,10],[7,9,11],[8,6,9],[9,7,10],[10,8,11],[11,9,8]];
let variant=OrionProgress.variant('garden'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,length=1,solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){return journeys[v][s];}
function target(){const w=stage===2?Math.floor(challenge()/2):stage+2;return w*(challenge()-w);}
function area(){return length*(challenge()-length);}
function setLength(n){if(solved||!Number.isInteger(n)||n<1||n>=challenge())return;length=n;state='ready';render();}
function resetTrial(){length=1;solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('garden')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;if(area()!==target())state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('moonflower');}render();if(solved&&stage<2)$('next').focus();}
function cols(n){return n+(n===1?' column':' columns');}
function rows(n){return n+(n===1?' row':' rows');}
function drawing(){const w=length,h=challenge()-w,u=Math.min(32,200/(challenge()-1)),x=(360-w*u)/2,y=(250-h*u)/2;
let cells='';for(let row=0;row<h;row++)for(let col=0;col<w;col++){const a=x+col*u,b=y+row*u;cells+=`<rect x="${a}" y="${b}" width="${u}" height="${u}" fill="#34594a" stroke="#afd0a2"/><text x="${a+u/2}" y="${b+u*.7}" text-anchor="middle" font-size="${u*.65}" fill="#ffdf87">${solved?'✿':'·'}</text>`;}
return `<svg viewBox="0 0 360 250" role="img" aria-label="${t(cols(w)+' and '+rows(h),w+' 欄、'+h+' 行')}">${cells}<rect x="${x}" y="${y}" width="${w*u}" height="${h*u}" fill="none" stroke="#e5bb77" stroke-width="4"/><g fill="#ffdfa4" font-size="16" text-anchor="middle"><text x="180" y="${y-8}">${w}</text><text x="${x-14}" y="130">${h}</text></g></svg>`;}
function hints(){const q=challenge(),w=stage===2?Math.floor(q/2):stage+2;return [t('Trace the gold edge, then count the squares inside.','沿金邊數一圈，再數裏面的方格。'),t('Multiply the number of columns by the number of rows.','把欄數乘以行數，就得到方格總數。'),t('Try '+w+' columns and '+(q-w)+' rows.','試試 '+w+' 欄、'+(q-w)+' 行。')];}
function render(){const q=challenge(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Walled Garden · Orion','圍牆花園 · Orion');$('stageTitle').textContent=t(`Garden ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 個花圃 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Gardens planted · ${p} / 3`,`已播種花圃 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('diagram').innerHTML=drawing();$('length').value=length;$('length').disabled=solved;$('length').max=q-1;$('lengthValue').textContent=String(length);$('length').setAttribute('aria-valuetext',t(cols(length),length+' 欄'));
$('goal').textContent=t('Fit exactly '+target()+' seeds inside a fence of '+(2*q)+' unit pieces.','用 '+(2*q)+' 段單位圍牆，圍出剛好可種 '+target()+' 顆種子的花圃。');$('reading').textContent=t(cols(length)+' × '+rows(q-length)+' = '+area()+' squares',length+' 欄 × '+(q-length)+' 行 = '+area()+' 格');$('reference').textContent=t('Fence: ','圍牆：')+[length,q-length,length,q-length].join(' + ')+' = '+2*q;
const messages={ready:['Shape the bed, then try planting.','調整花圃後，試試播種。'],wrong:area()<target()?['Some seeds have no space yet. Try a different shape.','有些種子還沒有位置。試試另一個形狀。']:['Some squares are empty. Try a different shape.','有些方格是空的。試試另一個形狀。'],success:['One seed in every square. The moonflowers bloom!','每格剛好一顆種子。月光花開了！']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;
$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('moonflower')?t('Moonflower Sigil saved in your collection.','月華符印已存入收藏。'):'';}
$('length').oninput=e=>setLength(Number(e.target.value));
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('garden',variant);observedVariant=OrionProgress.variant('garden');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('moonflower');render();};function syncProgress(){const v=OrionProgress.variant('garden'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('moonflower')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
